const data = $input.first().json.body ?? {};
const clean = x => typeof x === 'string' ? x.trim() : '';
const email = clean(data.email).toLowerCase();
const name = clean(data.name).slice(0,120);
const company = clean(data.company).slice(0,120);
const message = clean(data.message).slice(0,3000);
const consent = data.consent === true;
const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && !!name && consent;
const key = email + '|' + company.toLowerCase();
return [{json:{valid,reviewStatus:valid?'PENDING_HUMAN_REVIEW':'REJECTED',name,company,email,message,consent,dedupeKey:key,receivedAt:new Date().toISOString(),errors:[...(!name?['name_required']:[]),...(!email||!(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))?['invalid_email']:[]),...(!consent?['consent_required']:[])]}}];
